"use strict";(self.webpackChunkstrapi_docs=self.webpackChunkstrapi_docs||[]).push([[11928],{66209:e=>{e.exports=JSON.parse('{"tag":{"label":"GraphQL API","permalink":"/tags/graph-ql-api","allTagsPath":"/tags","count":9,"items":[{"id":"cms/api/graphql/advanced-policies","title":"Advanced policies for GraphQL","description":"Requests sent to the GraphQL API pass through Strapi\'s middlewares and policies system. Policies can be attached to resolvers to implement complex authorization rules, as shown in the present short guide.","permalink":"/cms/api/graphql/advanced-policies"},{"id":"cms/api/graphql/advanced-queries","title":"Advanced queries for GraphQL","description":"Strapi\'s GraphQL API resolves many queries automatically, but complex data access can require deeper relation fetching or chaining resolvers. The present short guide explains how to handle such advanced scenarios.","permalink":"/cms/api/graphql/advanced-queries"},{"id":"cms/migration/v4-to-v5/breaking-changes/upgrade-to-apollov4","title":"Apollo Server v3 upgraded to Apollo Server v4","description":"The upgrade from Apollo Server v3 to v4 and graphql ^15 to ^16.","permalink":"/cms/migration/v4-to-v5/breaking-changes/upgrade-to-apollov4"},{"id":"cms/backend-customization","title":"Back-end customization","description":"All elements of Strapi\'s back end, like routes, policies, middlewares, controllers, services, models, requests, responses, and webhooks, can be customized.","permalink":"/cms/backend-customization"},{"id":"cms/api/content-api","title":"Content API","description":"Learn more about Strapi 5\'s Content API","permalink":"/cms/api/content-api"},{"id":"cms/error-handling","title":"Error handling","description":"With Strapi\'s error handling feature it\'s easy to send and receive errors in your application.","permalink":"/cms/error-handling"},{"id":"cms/plugins/graphql","title":"GraphQL plugin","description":"Use a GraphQL endpoint in your Strapi project to fetch and mutate your content.","permalink":"/cms/plugins/graphql"},{"id":"cms/migration/v4-to-v5/breaking-changes/publication-state-removed","title":"publicationState is removed and replaced by status","description":"In Strapi 5, \'publicationState\' can no longer be used in Content API calls. The new status parameter can be used and accepts 2 different values, draft and published.","permalink":"/cms/migration/v4-to-v5/breaking-changes/publication-state-removed"},{"id":"cms/migration/v4-to-v5/breaking-changes/new-response-format","title":"Strapi 5 has a new, flattened response format for API calls","description":"In Strapi 5, the response format has been simplified and flattened, and attributes of requested content are no longer wrapped in an attributes object.","permalink":"/cms/migration/v4-to-v5/breaking-changes/new-response-format"}],"unlisted":false}}')}}]);